sys_script_include.script:
var servicedeskandhelpdesk  = Class.create();
servicedeskandhelpdesk .prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
	deskchange : function(){

		var current=this.getParameter("first"); 
		var previous=this.getParameter("second");


		var groups =  gs.getUser().getMyGroups();
		var ass_grp_pre=previous;

		var ass_grp = this.getTheValue(current); 
		var ass_grp_previous = this.getTheValue(previous);

		if (groups.includes(ass_grp_pre) ){

			var split = ass_grp.split(" ");
			var split_P = ass_grp_previous.split(" ");
			var first_current= split[0]+split[1];
			var second_current=split[2];
			var first_prev=split_P[0]+split_P[1];
			var second_prev=split_P[2];


			if(first_current == first_prev || second_current == second_prev){
				return "true";
			}
			else{

				return "false";
			}
		}
		else{

			return "false";
		}


	},

	getTheValue : function(sample){



		var gr =new GlideRecord('sys_user_group');
		gr.addQuery("sys_id","STARTSWITH",sample);
		gr.query();
		if(gr.next()){
			var displayvalue = gr.name;
			return displayvalue;
		}



	},

    type: 'servicedeskandhelpdesk '
});
